                ds.crestbridgeEvidence = Math.min(100, ds.crestbridgeEvidence + qg.cb);
                ds.harmonEvidence     = Math.min(100, ds.harmonEvidence     + qg.h);
                ds.novelaEvidence     = Math.min(100, ds.novelaEvidence     + qg.n);
                var calib = this.CALIB_BONUS[d.offeringResponse] || 0;
                ds.calibrationBonus = calib;
                periodScore = 5 + calib;
                newFindings = this._findingsP3(d.mgmtQuestionFocus, d.offeringResponse);

            } else if (period === 4) {
                var cos = ['vantara', 'crestbridge', 'harmon', 'novela'];
                var recs = {
                    vantara:    d.recVantara,
                    crestbridge: d.recCrestBridge,
                    harmon:     d.recHarmon,
                    novela:     d.recNovela
                };
                var evArr = {
                    vantara:    ds.vantaraEvidence,
                    crestbridge: ds.crestbridgeEvidence,
                    harmon:     ds.harmonEvidence,
                    novela:     ds.novelaEvidence
                };
                var detPts = 0;
                var fpPts  = 0;
                for (var i = 0; i < cos.length; i++) {
                    var co = cos[i];
                    var ev = evArr[co] / 100;
                    var maxP = this.MAX_DET_PTS[co];
                    if (recs[co] === this.CORRECT_RECS[co]) {
                        detPts += Math.round(maxP * ev);
                    } else if (co === 'harmon' && recs[co] === 'sell') {
                        detPts += Math.round(maxP * ev * 0.4);
                    } else {
                        fpPts += ev > 0.6 ? -12 : -4;
                    }
                }
                var subMult = d.adjustedMultipleNovela || 0;
                var valPts = 0;
                if (subMult > 0) {
                    var pctOff = Math.abs(subMult - this.NOVELA_TARGET_MULTIPLE) / this.NOVELA_TARGET_MULTIPLE;
                    if (pctOff <= 0.15)      valPts = 20;
                    else if (pctOff <= 0.30) valPts = 12;
                    else if (pctOff <= 0.50) valPts = 5;
                }
                ds.detectionBonus = detPts;
                ds.falsePenalty   = fpPts;
                ds.valuationBonus = valPts;
                // Calibration bonus is already credited in Round 3 (periodScore = 5 + calib),
                // matching the "+N pts" message shown to the student that round. Re-adding it here
                // double-counted it in the final total. (fix v1.1.0)
                periodScore = detPts + fpPts + valPts;
                newFindings = this._findingsP4(recs, evArr, detPts, fpPts, valPts);
            }

            ds.totalScore = (ds.totalScore || 0) + periodScore;
            ds.scoreHistory.push(Math.max(0, ds.totalScore));
            if (!ds.findingsLog) ds.findingsLog = [];
            ds.findingsLog = ds.findingsLog.concat(newFindings);

            // platform score: totalScore is bounded 0 to 151 at perfect play (same metric
            // getPerformanceSummary reports); scale that running total to 0-100 and clamp
            var overallScore = Math.max(0, Math.min(100, Math.round(100 * Math.max(0, ds.totalScore) / 151)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing(window.mySimulation ? window.mySimulation.state : { currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            return {
                period:              period,
                periodScore:         periodScore,
                totalScore:          ds.totalScore,
                vantaraEvidence:     ds.vantaraEvidence,
                crestbridgeEvidence: ds.crestbridgeEvidence,
                harmonEvidence:      ds.harmonEvidence,
                novelaEvidence:      ds.novelaEvidence
            };
        }

