        getChartData(state) {
            var hist = state.domainState.scoreHistory || [];
            var roundWord = this._t('round_label');
            var labels = [1, 2, 3, 4].map(function(n) { return roundWord + ' ' + n; }).slice(0, hist.length);
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: hist }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            // Clamp to 0 for display consistency with the on-screen score (the raw running total can
            // dip slightly negative on poor play; classification thresholds are unaffected). (v1.1.0)
            var total = Math.max(0, last.results ? (last.results.totalScore || 0) : 0);
            // performance and insights are translation keys, not literal text: the Open player's
            // overlay renderer looks up any lowercase_underscore value through t() automatically
            var performance, insights;
            if (total >= 120) {
                performance = 'perf_elite';
                insights = ['insight_elite_1', 'insight_elite_2'];
            } else if (total >= 90) {
                performance = 'perf_competent';
                insights = ['insight_competent_1', 'insight_competent_2'];
            } else if (total >= 60) {
                performance = 'perf_developing';
                insights = ['insight_developing_1', 'insight_developing_2'];
            } else {
                performance = 'perf_beginner';
                insights = ['insight_beginner_1', 'insight_beginner_2'];
            }
            return { totalScore: total, performance: performance, insights: insights };
        }

        getHint(state, results) {
            var period = state.currentPeriod;
            var ds = state.domainState;
            if (period === 1 && ds.novelaEvidence < 45) {
                return window.mySimulation.t('hint_novela_proxy');
            }
            if (period === 2 && ds.novelaEvidence < 60) {
                return window.mySimulation.t('hint_balance');
            }
            if (period === 3 && ds.harmonEvidence < 50) {
                return window.mySimulation.t('hint_harmon');
            }
            if (period === 4 && (ds.vantaraEvidence + ds.novelaEvidence) < 100) {
                return window.mySimulation.t('hint_evidence_gaps');
            }
            return null;
        }

