        // --- Private Helpers ---

        _t(key, params) {
            return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key, params) : key;
        }

        _updateBriefing(state) {
            var period = (state && state.currentPeriod) ? state.currentPeriod : 1;
            var ds     = (state && state.domainState)  ? state.domainState  : null;

            // Switch period controls
            for (var i = 1; i <= 4; i++) {
                var ctrl = document.getElementById('period' + i + 'Controls');
                if (ctrl) ctrl.style.display = (i === period) ? 'block' : 'none';
            }

            // Update briefing text
            var briefEl = document.getElementById('briefingText');
            if (briefEl && this.BRIEFINGS[period]) {
                briefEl.innerHTML = this._t(this.BRIEFINGS[period]);
            }

            if (!ds) return;

            // Update evidence bars and company card states
            var companies = [
                { ev: ds.vantaraEvidence    || 0, barId: 'vantaraEvBar',    findId: 'vantaraFinding',    cardId: 'vantaraCard'    },
                { ev: ds.crestbridgeEvidence || 0, barId: 'crestbridgeEvBar', findId: 'crestbridgeFinding', cardId: 'crestbridgeCard' },
                { ev: ds.harmonEvidence     || 0, barId: 'harmonEvBar',     findId: 'harmonFinding',     cardId: 'harmonCard'     },
                { ev: ds.novelaEvidence     || 0, barId: 'novelaEvBar',     findId: 'novelaFinding',     cardId: 'novelaCard'     }
            ];
            for (var j = 0; j < companies.length; j++) {
                var co = companies[j];
                var barEl = document.getElementById(co.barId);
                if (barEl) barEl.style.width = Math.min(100, co.ev) + '%';

                var findEl = document.getElementById(co.findId);
                if (findEl) {
                    if (co.ev >= 70) {
                        findEl.innerHTML = '<span class="redflag-sim-badge-red">' + this._t('badge_high_risk') + '</span>';
                    } else if (co.ev >= 40) {
                        findEl.innerHTML = '<span class="redflag-sim-badge-amber">' + this._t('badge_elevated') + '</span>';
                    } else if (co.ev > 0) {
                        findEl.innerHTML = '<span class="rf-blue">' + this._t('badge_screening_complete') + '</span>';
                    } else {
                        findEl.textContent = '—';
                    }
                }

                var cardEl = document.getElementById(co.cardId);
                if (cardEl) {
                    cardEl.classList.remove('redflag-sim-co-flagged', 'redflag-sim-co-monitoring', 'redflag-sim-co-clear');
                    if (co.ev >= 70)      cardEl.classList.add('redflag-sim-co-flagged');
                    else if (co.ev >= 40) cardEl.classList.add('redflag-sim-co-monitoring');
                    else if (co.ev > 0)   cardEl.classList.add('redflag-sim-co-clear');
                }
            }

            // Update findings log
            var logEl = document.getElementById('findingsLog');
            if (logEl && ds.findingsLog && ds.findingsLog.length) {
                logEl.innerHTML = ds.findingsLog.map(function(f) {
                    return '<div class="redflag-sim-finding-item">' + f + '</div>';
                }).join('');
                logEl.scrollTop = logEl.scrollHeight;
            }
        }

        _findingsP1(method) {
            var t = { 1: 'A', 2: 'B', 3: 'C', 4: 'D' }[method];
            var out = ['<span class="rf-dim">' + this._t('f1_header', { opt: t }) + '</span>'];
            if (method === 1) {
                out.push(this._t('f1_A1'));
                out.push(this._t('f1_A2'));
                out.push(this._t('f1_A3'));
                out.push(this._t('f1_A4'));
            } else if (method === 2) {
                out.push(this._t('f1_B1'));
                out.push(this._t('f1_B2'));
                out.push(this._t('f1_B3'));
                out.push(this._t('f1_B4'));
            } else if (method === 3) {
                out.push(this._t('f1_C1'));
                out.push(this._t('f1_C2'));
                out.push(this._t('f1_C3'));
                out.push(this._t('f1_C4'));
            } else {
                out.push(this._t('f1_D1'));
                out.push(this._t('f1_D2'));
                out.push(this._t('f1_D3'));
                out.push(this._t('f1_D4'));
            }
            return out;
        }

        _findingsP2(method, ds) {
            var t = { 1: 'A', 2: 'B', 3: 'C', 4: 'D' }[method];
            var out = ['<span class="rf-dim">' + this._t('f2_header', { opt: t }) + '</span>'];
            if (method === 1) {
                out.push(this._t('f2_A1'));
                out.push(this._t('f2_A2'));
            } else if (method === 2) {
                out.push(this._t('f2_B1'));
                out.push(this._t('f2_B2'));
                out.push(this._t('f2_B3'));
            } else if (method === 3) {
                out.push(this._t('f2_C1'));
                out.push(this._t('f2_C2'));
                out.push(this._t('f2_C3'));
                out.push(this._t('f2_C4'));
            } else {
                out.push(this._t('f2_D1'));
                out.push(this._t('f2_D2'));
            }
            return out;
        }

        _findingsP3(qFocus, offering) {
            var out = ['<span class="rf-dim">' + this._t('f3_header') + '</span>'];
            if (qFocus === 1) {
                out.push(this._t('f3_q1'));
            } else if (qFocus === 2) {
                out.push(this._t('f3_q2'));
            } else if (qFocus === 3) {
                out.push(this._t('f3_q3'));
            } else {
                out.push(this._t('f3_q4'));
            }
            if (offering === 1) {
                out.push(this._t('f3_o1'));
            } else if (offering === 2) {
                out.push(this._t('f3_o2'));
            } else if (offering === 3) {
                out.push(this._t('f3_o3'));
            } else {
                out.push(this._t('f3_o4'));
            }
            return out;
        }

        _findingsP4(recs, evArr, detPts, fpPts, valPts) {
            var out = ['<span class="rf-dim">' + this._t('f4_header') + '</span>'];
            var correct = this.CORRECT_RECS;
            var names = { vantara: 'Vantara', crestbridge: 'CrestBridge', harmon: 'Harmon', novela: 'Novela' };
            var keys = ['vantara', 'crestbridge', 'harmon', 'novela'];
            for (var i = 0; i < keys.length; i++) {
                var co = keys[i];
                var ev = Math.round(evArr[co] || 0);
                var recWord = this._t('rec_' + (recs[co] || 'sell')).toUpperCase();
                var isCorrect = recs[co] === correct[co];
                var isPartial = co === 'harmon' && recs[co] === 'sell';
                if (isCorrect) {
                    out.push(this._t('f4_row_correct', { name: names[co], rec: recWord, ev: ev }));
                } else if (isPartial) {
                    out.push(this._t('f4_row_partial', { name: names[co], rec: recWord, hold: this._t('rec_hold').toUpperCase() }));
                } else {
                    var wrongKey = ev > 60 ? 'f4_row_wrong_high' : 'f4_row_wrong_low';
                    out.push(this._t(wrongKey, { name: names[co], rec: recWord, correct: this._t('rec_' + correct[co]).toUpperCase(), ev: ev }));
                }
            }
            out.push(this._t('f4_footer', { det: detPts, fp: fpPts, val: valPts }));
            if (valPts === 20) {
                out.push(this._t('f4_val_full'));
            } else if (valPts >= 12) {
                out.push(this._t('f4_val_p30'));
            } else if (valPts >= 5) {
                out.push(this._t('f4_val_p50'));
            } else {
                out.push(this._t('f4_val_none'));
            }
            return out;
        }

    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new RedFlagAdapter(), {
            simulationType: 'redflag_audit',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

})();
